Lemma bptr_eq_dec : forall x y : bptr, {x = y} + {x <> y}.
Proof.
  intros [[n1 z1] w1] [[n2 z2] w2].
  destruct (N.eq_dec n1 n2) as [<-|]; [| right; congruence].
  destruct (Z.eq_dec z1 z2) as [<-|]; [| right; congruence].
  destruct (Z.eq_dec w1 w2) as [<-|]; [left; reflexivity| right; congruence].
Qed.

(* [comment removed for export] *)
Definition mut_lb (lbrm : bptr -> list block -> list block) (LB : list block) (S S' : srep) (LB' : list block) : Prop :=
  (sown S' = sown S /\ LB' = LB)
  \/ (exists p' A' alloc', sown S' = Some (p', A', alloc') /\
        LB' = (p', A', alloc') :: match sown S with None => LB | Some (p, _, _) => lbrm p LB end).

(* [comment removed for export] *)
Lemma lor1_even : forall a, 0 <= a -> a mod 2 = 0 -> Z.lor a 1 = a + 1.
Proof.
  intros a Ha EV.
  assert (L : Z.land a 1 = 0). { change 1 with (Z.ones 1). rewrite Z.land_ones by lia. exact EV. }
  rewrite <- Z.lxor_lor by exact L. symmetry. apply Z.add_nocarry_lxor. exact L.
Qed.

(* [comment removed for export] *)
Lemma Z_to_bv8_low : forall (b : byte) r, 0 <= r -> Z_to_bv 8 (bv_unsigned b + 256 * r) = b.
Proof.
  intros b r Hr. apply bv_eq. rewrite Z_to_bv_unsigned. unfold bv_wrap, bv_modulus. change (2 ^ Z.of_N 8) with 256.
  pose proof (bv_unsigned_in_range 8 b) as R. unfold bv_modulus in R. change (2 ^ Z.of_N 8) with 256 in R.
  Z.div_mod_to_equations. nia.
Qed.

Lemma Z_to_le_bytes_le_val : forall bs : list byte, Z_to_le_bytes (length bs) (le_val (map bv_unsigned bs)) = bs.
Proof.
  induction bs as [|b bs IH]; [reflexivity|]. cbn [length map le_val Z_to_le_bytes].
  pose proof (le_val_range (map bv_unsigned bs) (bytes_ok_map bs)) as R.
  pose proof (bv_unsigned_in_range 8 b) as Rb. unfold bv_modulus in Rb. change (2 ^ Z.of_N 8) with 256 in Rb.
  f_equal; [apply Z_to_bv8_low; lia|].
  rewrite Z.shiftr_div_pow2 by lia. change (2^8) with 256.
  replace ((bv_unsigned b + 256 * le_val (map bv_unsigned bs)) / 256) with (le_val (map bv_unsigned bs)) by (Z.div_mod_to_equations; nia).
  exact IH.
Qed.

Lemma le8_le_bytes_to_word : forall bs : list byte, length bs = 8%nat -> le8 (le_bytes_to_word bs) = bs.
Proof.
  intros bs L. unfold le8, word_to_le_bytes, le_bytes_to_word. rewrite Z_to_bv_unsigned, bytes_le_to_Z_le_val.
  pose proof (le_val_range (map bv_unsigned bs) (bytes_ok_map bs)) as R. rewrite length_map, L in R. change (256 ^ Z.of_nat 8) with (2^64) in R.
  rewrite (bv_wrap_small 64) by (unfold bv_modulus; cbn; lia). rewrite <- L. apply Z_to_le_bytes_le_val.
Qed.

Lemma short_cells_word8 : forall m a bs junk,
  rw_cells rsegs m a (short_cells bs junk) -> zlength bs <= 22 ->
  exists (w : word) rest, rw_cells rsegs m a [C8 w; CB 16 rest]
    /\ Z.land (bv_unsigned w) 1 = 0 /\ Z.land (bv_unsigned w) 255 = 2 * zlength bs
    /\ Z.shiftr ((Z.shiftl (bv_unsigned w) 56) mod 2^64) 57 = zlength bs.
Proof.
  intros m a bs junk HS HL. destruct (short_cells_wordview m a bs junk HS HL) as (b7 & rest & L7 & HW).
  exists (le_bytes_to_word (b8 (2 * zlength bs) :: b7)), rest.
  assert (U : bv_unsigned (le_bytes_to_word (b8 (2 * zlength bs) :: b7)) = short_w0 bs b7).
  { unfold short_w0. rewrite bv_extract_unsigned, Z.shiftr_0_r.
    pose proof (bv_unsigned_in_range 64 (le_bytes_to_word (b8 (2 * zlength bs) :: b7))) as R.
    rewrite bv_wrap_small by lia. reflexivity. }
  rewrite U. split; [| split; [apply short_w0_land1; assumption| split; [apply short_w0_byte; assumption| apply short_w0_size; assumption]]].
  pose proof HW as [[WF _] _]. cbn in WF.
  eapply rw_cells_recut; [exact HW| cbn; repeat split; lia|].
  cbn [cells_bytes cbytes app]. rewrite le8_le_bytes_to_word by (cbn; lia). reflexivity.
Qed.
