Section HH.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Lemma hh_lb_remove_cons_ne : forall p b LB, blk_id b <> p -> hs_lb_remove H p (b :: LB) = b :: hs_lb_remove H p LB.
  Proof. intros. apply (proj1 (proj2 (hh_lb_remove H HH))). assumption. Qed.

  Lemma hh_lb_remove_In : forall p LB b, In b (hs_lb_remove H p LB) -> In b LB.
  Proof. intros. eapply (proj2 (proj2 (hh_lb_remove H HH))). eassumption. Qed.

  Lemma hh_lb_remove_keep : forall p LB b,
    List.NoDup (map blk_id LB) -> In b LB -> blk_id b <> p -> In b (hs_lb_remove H p LB).
  Proof.
    intros p LB. induction LB as [|c LB IH]; intros b ND Hin NE; [destruct Hin|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct (bptr_eq_dec (blk_id c) p) as [E|NE'].
    - destruct c as [[pc Ac] nc]. cbn in E. subst pc.
      rewrite (proj1 (hh_lb_remove H HH)) by exact NI.
      destruct Hin as [<-|Hin]; [cbn in NE; congruence| exact Hin].
    - rewrite hh_lb_remove_cons_ne by exact NE'. destruct Hin as [<-|Hin]; [left; reflexivity| right]. apply IH; assumption.
  Qed.

  (* [comment removed for export] *)
  Lemma hh_lb_remove_fresh : forall s LB m p' A' n' p,
    hs_RHEAP H s ((p', A', n') :: LB) m -> In p (map blk_id LB) ->
    hs_lb_remove H p ((p', A', n') :: LB) = (p', A', n') :: hs_lb_remove H p LB.
  Proof.
    intros s LB m p' A' n' p HP Hin. apply hh_lb_remove_cons_ne. cbn.
    pose proof (hh_nodup H HH _ _ _ HP) as ND. cbn in ND. inversion ND; subst. congruence.
  Qed.

  (* [comment removed for export] *)
  Lemma nodup_blk_eq : forall LB b b', List.NoDup (map blk_id LB) -> In b LB -> In b' LB -> blk_id b = blk_id b' -> b = b'.
  Proof.
    induction LB as [|c LB IH]; intros b b' ND Hb Hb' E; [destruct Hb|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct Hb as [<-|Hb]; destruct Hb' as [<-|Hb']; [reflexivity| | | apply IH; assumption].
    - exfalso. apply NI. rewrite E. apply in_map. exact Hb'.
    - exfalso. apply NI. rewrite <- E. apply in_map. exact Hb.
  Qed.

  (* [comment removed for export] *)
  Lemma rclient_range_after_free : forall s LB m p Ap np s2 m2 p' A' n' SP A n,
    hs_RHEAP H s LB m -> In (p, Ap, np) LB -> hs_RHEAP H s2 ((p', A', n') :: LB) m2 ->
    rclient_range LB SP A n -> (A + n <= Ap \/ Ap + np <= A) -> 0 < n ->
    rclient_range (hs_lb_remove H p ((p', A', n') :: LB)) SP A n.
  Proof.
    intros s LB m p Ap np s2 m2 p' A' n' SP A n HP Hin HP2 HR DJ Hn.
    rewrite (hh_lb_remove_fresh _ _ _ _ _ _ _ HP2) by (apply in_map_iff; exists (p, Ap, np); split; [reflexivity| exact Hin]).
    destruct HR as [K|[K|(b & Hb & K1 & K2)]]; [left; exact K| right; left; exact K| right; right].
    exists b. split; [| split; assumption]. right.
    apply hh_lb_remove_keep; [exact (hh_nodup H HH _ _ _ HP)| exact Hb|].
    intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
    subst b. cbn in K1, K2.
    pose proof (hh_blocks H HH _ _ _ _ HP Hin) as (_ & _ & R3 & _). cbn in R3. lia.
  Qed.

  Lemma xpres_after_free : forall s LB m p Ap np s2 m2 p' A' n' SP SP' X m3 m4,
    hs_RHEAP H s LB m -> In (p, Ap, np) LB -> hs_RHEAP H s2 ((p', A', n') :: LB) m2 ->
    rheap_pres (hs_lb_remove H p ((p', A', n') :: LB)) SP' m3 m4 -> SP' <= SP ->
    (forall a, Ap <= a < Ap + np -> rin_ivs X a) ->
    xpres LB SP X m3 m4.
  Proof.
    intros s LB m p Ap np s2 m2 p' A' n' SP SP' X m3 m4 HP Hin HP2 PRES HS HX a Ha [HC NX].
    apply PRES; [exact Ha|].
    rewrite (hh_lb_remove_fresh _ _ _ _ _ _ _ HP2) by (apply in_map_iff; exists (p, Ap, np); split; [reflexivity| exact Hin]).
    destruct HC as [K|[K|(b & Hb & K)]]; [left; lia| right; left; exact K| right; right].
    exists b. split; [| exact K]. right.
    apply hh_lb_remove_keep; [exact (hh_nodup H HH _ _ _ HP)| exact Hb|].
    intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
    subst b. cbn in K. apply NX. apply HX. exact K.
  Qed.

  (* [comment removed for export] *)
  Lemma fresh_in_after_free : forall s LB m p Ap np s2 m2 p' A' n',
    hs_RHEAP H s LB m -> In (p, Ap, np) LB -> hs_RHEAP H s2 ((p', A', n') :: LB) m2 ->
    In (p', A', n') (hs_lb_remove H p ((p', A', n') :: LB))
    /\ (forall b, In b (hs_lb_remove H p ((p', A', n') :: LB)) -> In b ((p', A', n') :: LB)).
  Proof.
    intros s LB m p Ap np s2 m2 p' A' n' HP Hin HP2.
    rewrite (hh_lb_remove_fresh _ _ _ _ _ _ _ HP2) by (apply in_map_iff; exists (p, Ap, np); split; [reflexivity| exact Hin]).
    split; [left; reflexivity|]. intros b [<-|Hb]; [left; reflexivity| right]. eapply hh_lb_remove_In. exact Hb.
  Qed.
End HH.

End HCW.

